#if UNITY_EDITOR || DEVELOPMENT_BUILD
using System;
using System.Collections;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using TMPro;
using UnityEngine;
using UnityEngine.UI;
public sealed class PrivateChamberCapture:MonoBehaviour
{
 string folder;readonly List<string> results=new List<string>();
 [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.BeforeSceneLoad)]static void Begin(){if(!Environment.GetCommandLineArgs().Contains("-private-chamber-capture"))return;string path=Path.GetFullPath(Path.Combine(Application.dataPath,"../Captures/PrivateChamber"));Directory.CreateDirectory(path);SaveGames.TestRoot=Path.Combine(path,"Saves");Directory.CreateDirectory(SaveGames.TestRoot);VariableSingleton.TestSavePath=Path.Combine(SaveGames.TestRoot,"checkpoint.besieged.json");var go=new GameObject("Maritime city verification");DontDestroyOnLoad(go);go.AddComponent<PrivateChamberCapture>().folder=path;}
 void Check(bool value,string label){if(!value)throw new Exception(label);results.Add("PASS "+label);}
 string State()=>JsonUtility.ToJson(VariableSingleton.Instance.CaptureState());
 Button Button(Transform root,string text)=>root.GetComponentsInChildren<Button>().First(b=>b.GetComponentInChildren<TMP_Text>()?.text==text);
 IEnumerator Start(){File.WriteAllText(Path.Combine(folder,"checks.txt"),"RUNNING");var stack=new Stack<IEnumerator>();stack.Push(Run());while(stack.Count>0){object next=null;bool more=false;Exception error=null;try{more=stack.Peek().MoveNext();if(more)next=stack.Peek().Current;}catch(Exception ex){error=ex;}if(error!=null){File.WriteAllLines(Path.Combine(folder,"details.txt"),results);File.WriteAllText(Path.Combine(folder,"checks.txt"),"FAILED "+error);Application.Quit(1);yield break;}if(!more){stack.Pop();continue;}if(next is IEnumerator nested)stack.Push(nested);else yield return next;}File.WriteAllLines(Path.Combine(folder,"details.txt"),results);File.WriteAllText(Path.Combine(folder,"checks.txt"),"PRIVATE_CHAMBER_CHECKS "+results.Count+" passed");Application.Quit();}
 IEnumerator Run(){Application.runInBackground=true;AudioListener.volume=0;yield return null;SaveMenu.StartCampaign(false);float deadline=Time.realtimeSinceStartup+20;while((!VariableSingleton.IsInitialized||FindObjectOfType<ManagerUI>()==null)&&Time.realtimeSinceStartup<deadline)yield return null;Check(VariableSingleton.IsInitialized,"campaign initialized");yield return new WaitForSecondsRealtime(.3f);CampaignHUD.Instance.DismissReport();var council=CouncilUI.For(FindObjectOfType<ManagerUI>());
 foreach(var size in new[]{new Vector2Int(1600,900),new Vector2Int(1280,720)}){Screen.SetResolution(size.x,size.y,false);yield return new WaitForSecondsRealtime(.3f);council.Palace();yield return null;var entry=GameObject.Find("Hotspot · The Emperor's chamber").GetComponent<LocationHotspot>();Check(entry!=null,"palace door exists");entry.Action.Invoke();yield return null;var painting=GameObject.Find("Private chamber painting");Check(painting!=null,"door opens private chamber");Check(painting.GetComponent<UnityEngine.UI.Image>().sprite!=null,"chamber artwork loaded");Check(painting.GetComponent<UnityEngine.UI.RawImage>()==null,"single image component");string before=State();council.PrivateChamber();yield return null;Check(State()==before,"repeated room inspection preserves campaign and RNG");yield return Capture("chamber-"+size.x);
 var mirror=GameObject.Find("Hotspot · The Emperor's reflection").GetComponent<LocationHotspot>();Check(mirror.IsRaycastLocationValid(RectTransformUtility.WorldToScreenPoint(null,mirror.rectTransform.TransformPoint(new Vector3(mirror.rectTransform.rect.xMin+mirror.rectTransform.rect.width*.775f,mirror.rectTransform.rect.yMin+mirror.rectTransform.rect.height*.56f))),null),"mirror silhouette includes glass");mirror.Action.Invoke();yield return null;Check(GameObject.Find("Council screen").GetComponentsInChildren<TMP_Text>().Any(t=>t.text.StartsWith("HEALTH · ")),"mirror displays current health");yield return Capture("reflection-"+size.x);ControlSingleton.Instance.GoBack();yield return null;Check(GameObject.Find("Private chamber painting")!=null,"reflection Back returns to chamber");
 GameObject.Find("Hotspot · Decision Journal").GetComponent<LocationHotspot>().Action.Invoke();yield return null;Check(DecisionJournal.Close(),"book opens existing journal");yield return null;GameObject.Find("Hotspot · Return to the Palace").GetComponent<LocationHotspot>().Action.Invoke();yield return null;Check(GameObject.Find("Location painting")!=null,"door returns to Palace");council.PrivateChamber();yield return null;ControlSingleton.Instance.GoBack();yield return null;Check(GameObject.Find("Location painting")!=null,"Back returns to Palace");Check(State()==before,"mirror journal and return have no gameplay effect");} }
 IEnumerator Capture(string name){yield return new WaitForSecondsRealtime(.1f);Canvas.ForceUpdateCanvases();var go=new GameObject("Maritime capture camera",typeof(Camera));var camera=go.GetComponent<Camera>();camera.orthographic=true;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=ImperialTheme.Navy;camera.nearClipPlane=.1f;camera.farClipPlane=100;var canvases=FindObjectsOfType<Canvas>().Where(c=>c.isRootCanvas).ToArray();var modes=canvases.Select(c=>c.renderMode).ToArray();var cameras=canvases.Select(c=>c.worldCamera).ToArray();var distances=canvases.Select(c=>c.planeDistance).ToArray();var target=RenderTexture.GetTemporary(Screen.width,Screen.height,24);var previous=RenderTexture.active;Texture2D shot=null;try{camera.targetTexture=target;foreach(var c in canvases){c.renderMode=RenderMode.ScreenSpaceCamera;c.worldCamera=camera;c.planeDistance=10;}Canvas.ForceUpdateCanvases();camera.Render();RenderTexture.active=target;shot=new Texture2D(target.width,target.height,TextureFormat.RGB24,false);shot.ReadPixels(new Rect(0,0,target.width,target.height),0,0);shot.Apply();File.WriteAllBytes(Path.Combine(folder,name+".png"),shot.EncodeToPNG());}finally{RenderTexture.active=previous;for(int i=0;i<canvases.Length;i++){canvases[i].renderMode=modes[i];canvases[i].worldCamera=cameras[i];canvases[i].planeDistance=distances[i];}camera.targetTexture=null;RenderTexture.ReleaseTemporary(target);if(shot!=null)Destroy(shot);Destroy(go);}}
}
#endif
